"""Execute the search queries generated by the reflection agent."""

import json

from langchain_core.messages import AIMessage, BaseMessage, ToolMessage

from search import tavily_tool

# Tool calls whose ``search_queries`` argument should be executed by Tavily.
SUPPORTED_TOOLS = {"AnswerQuestion", "ReviseAnswer"}


def execute_tools(state: list[BaseMessage]) -> list[BaseMessage]:
    """Run the Tavily searches requested by the last AI message.

    The previous node is expected to be an ``AIMessage`` carrying one or more
    tool calls (``AnswerQuestion`` or ``ReviseAnswer``) whose arguments hold a
    ``search_queries`` list. For every supported tool call a single
    ``ToolMessage`` is returned, keyed by the originating ``tool_call_id`` so
    that the conversation stays well formed.

    A missing or unsupported last message produces no tool messages. A search
    that raises is recorded as an error string rather than aborting the whole
    workflow, so one failing query does not discard the other results.
    """

    if not state:
        return []

    last_ai_message = state[-1]
    if not isinstance(last_ai_message, AIMessage):
        return []

    tool_messages: list[BaseMessage] = []

    for tool_call in getattr(last_ai_message, "tool_calls", None) or []:
        if tool_call.get("name") not in SUPPORTED_TOOLS:
            continue

        call_id = tool_call.get("id")
        queries = (tool_call.get("args") or {}).get("search_queries", []) or []

        query_result = {}
        for query in queries:
            try:
                query_result[query] = tavily_tool.invoke(query)
            except Exception as exc:  # noqa: BLE001 - surfaced to the agent, not swallowed
                query_result[query] = f"Search failed for {query!r}: {exc}"

        tool_messages.append(
            ToolMessage(content=json.dumps(query_result), tool_call_id=call_id)
        )

    return tool_messages
